  }

  /// Reverse `lhs` by `rhs`, i.e. changing it `lhs` to the position `rhs` bytes before `lhs`.
  public static func -= (lhs: inout AbsolutePosition, rhs: SourceLength) {
    lhs = lhs - rhs
